// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/me/verification", wrapper.GetMyVerification)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/v1/me/verification/draft", wrapper.SaveVerificationDraft)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/me/verification/evidence", wrapper.UploadVerificationEvidence)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/v1/me/verification/evidence/{evidenceId}", wrapper.DeleteVerificationEvidence)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/me/verification/submit", wrapper.SubmitVerification)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/clinics/{clinicId}/verification", wrapper.GetClinicVerification)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/v1/clinics/{clinicId}/verification/draft", wrapper.SaveClinicVerificationDraft)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/clinics/{clinicId}/verification/evidence", wrapper.UploadClinicVerificationEvidence)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/v1/clinics/{clinicId}/verification/evidence/{evidenceId}", wrapper.DeleteClinicVerificationEvidence)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/clinics/{clinicId}/verification/submit", wrapper.SubmitClinicVerification)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/reviews/queue", wrapper.ListVerificationQueue)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/reviews/cases/{caseId}", wrapper.GetVerificationReviewCase)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/reviews/cases/{caseId}/evidence/{evidenceId}", wrapper.GetVerificationEvidence)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/reviews/cases/{caseId}/decision", wrapper.RecordVerificationDecision)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/reviews/cases/{caseId}/evidence/{evidenceId}/prohibited-id", wrapper.ReportProhibitedIdDocument)
	})

	return r
}

